SELECT ?person ?personLabel ?occupation WHERE {
  VALUES ?workTitle {"Che strano chiamarsi Federico"}
  ?work wdt:P31 wd:Q11424;                   # instance of film
        rdfs:label ?workLabel.
  FILTER(LANG(?workLabel) = "it")
  FILTER(CONTAINS(?workLabel, ?workTitle))

  ?person wdt:P800 ?work.                    # author/creator of the work
  OPTIONAL { ?person wdt:P106 ?occupation. } # occupation

  # Check if person also associated with "Yes Minister"
  ?tvShow wdt:P31 wd:Q5398426;               # TV series
          rdfs:label ?tvLabel.
  FILTER(CONTAINS(LCASE(?tvLabel), "yes minister"))

  ?person wdt:P161 ?tvShow.                  # cast or crew member of "Yes Minister"

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} LIMIT 10

UNION

SELECT ?person ?personLabel ?occupation WHERE {
  ?person wdt:P106 wd:Q2526255.               # director occupation
  ?person wdt:P800 ?work.
  ?work rdfs:label ?workLabel.
  FILTER(LANG(?workLabel) = "it")
  FILTER(CONTAINS(?workLabel, "Che strano chiamarsi Federico"))

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} LIMIT 10

UNION

