SELECT ?actor ?actorLabel WHERE {
  # Find actors who starred in "Hollywood Goes Classical" performed at Dorothy Chandler Pavilion
  ?performance wdt:P31/wdt:P279* wd:Q160866;                 # instance of theatrical performance or subclass
               rdfs:label "Hollywood Goes Classical"@en;
               wdt:P276 wd:Q1145428;                       # located at Dorothy Chandler Pavilion

  ?performance wdt:P161 ?actor.                              # cast member of the performance

  # Restrict actor nationality to England/UK (English actor)
  ?actor wdt:P27 ?country.
  FILTER(?country = wd:Q145 || ?country = wd:Q21)           # Q145 = United Kingdom, Q21 = England

  # Find actors who starred in "Lethal Obsession" film
  ?film wdt:P31/wdt:P279* wd:Q11424;                        # instance of film or subclass
        rdfs:label "Lethal Obsession"@en;
        wdt:P161 ?actor.                                     # cast member of the film

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

