SELECT ?coDirector ?coDirectorLabel WHERE {
  # Identify the film "Winning America"
  ?film rdfs:label "Winning America"@en .
  ?film wdt:P31 wd:Q11424 .  # instance of film

  # Find directors and co-directors of the film
  ?film wdt:P57 ?coDirector .

  # Confirm the person is known as a director
  ?coDirector wdt:P106 wd:Q2526255 .  # occupation: film director

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?harleyKnolesLabel WHERE {
  # Find Harley Knoles as a person with director occupation
  ?harleyKnoles rdfs:label "Harley Knoles"@en .
  ?harleyKnoles wdt:P106 wd:Q2526255 .  # occupation film director

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?coDirector ?coDirectorLabel WHERE {
  ?film wdt:P31 wd:Q11424;          # instance of film
        rdfs:label "Winning America"@en;
        wdt:P57 ?director.
  ?film wdt:P161 ?castMember.        # optional to confirm it's the right film
  ?film wdt:P57 ?coDirector.         # co-directors are listed as directors
  FILTER (?coDirector != wd:QXXXX)   # exclude Harley Knoles if known QID (needs identification if available)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 10

# This query aims to identify all directors credited for "Winning America," including any co-directors. 
# The co-director is, by definition, a director, so any named director besides Harley Knoles would satisfy the condition.
# If there is only one director, then there is no co-director and the claim might be false or partially true.

SELECT ?coDirector ?coDirectorLabel WHERE {
  ?film wdt:P31 wd:Q11424;           # instance of film
        rdfs:label "Winning America"@en;
        wdt:P57 ?director;           # director property
        OPTIONAL { ?film wdt:P161 ?cast }.
  # Retrieve co-directors, if co-director is represented specifically, or all directors
  # Since co-director property may not exist specifically, get all directors
  # Then retrieve Harley Knoles separately for confirmation
  # Check if ?director is Harley Knoles or another director
  # Query all directors associated with Winning America
  # Alternatively, list co-director if the property exists
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
} 

UNION

SELECT ?harleyKnoles WHERE {
  ?harleyKnoles rdfs:label "Harley Knoles"@en;
                 wdt:P106 wd:Q2526255.     # profession film director
}

# Optional extension: check if co-director is known as a director by querying their directorial profession or film director status

SELECT ?coDirector ?coDirectorLabel ?harleyKnolesLabel WHERE {
  # Find the film "Winning America"
  ?film wdt:P31 wd:Q11424;           # instance of film
        rdfs:label "Winning America"@en;
        wdt:P57 ?director.

  # Find all directors including co-directors of the film
  ?film wdt:P57 ?harleyKnoles;
        wdt:P57 ?coDirector.

  # Ensure coDirector is a director (co-director is normally included in director property)
  # Include Harley Knoles as a director entity
  FILTER(?harleyKnoles = wd:Q2149783)  # Assuming Harley Knoles has this Wikidata QID; otherwise search by label
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 10

SELECT ?coDirector ?coDirectorLabel WHERE {
  ?film wdt:P31 wd:Q11424;        # instance of film
        rdfs:label "Winning America"@en;
        wdt:P57 ?director;        # director
        wdt:P57 ?coDirector.      # co-director as director property, showing multiple directors
  FILTER (?coDirector != ?director)
  ?coDirector wdt:P106 wd:Q2526255.  # occupation: film director
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?coDirector ?coDirectorLabel WHERE {
  ?film wdt:P31 wd:Q11424;                    # instance of film
        rdfs:label "Winning America"@en;
        wdt:P57 ?director.
  ?film wdt:P161 ?coDirector.                 # cast or equivalent link
  # Check for co-director property or additional director linked to this film
  {
    ?film wdt:P77 ?coDirector.                 # co-director (if available)
  }
  UNION
  {
    ?film p:P57 ?directorStmt.
    ?directorStmt pq:P530 ?coDirector.        # qualifier for co-director role on director statement
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

